payload.arguments:
{"description":"Create Nginx server config for HTTPS on 8443","cmd":"cat > /etc/nginx/sites-available/git-deploy <<'EOF'
# Git-deployed project: HTTPS on 8443
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/ssl/server.crt;
    ssl_certificate_key /etc/nginx/ssl/server.key;

    # main branch content is served as the web root;
    # dev branch content is served under /dev/
    root /srv/www;
    index index.html;

    access_log off;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
ln -sf /etc/nginx/sites-available/git-deploy /etc/nginx/sites-enabled/git-deploy
rm -f /etc/nginx/sites-enabled/default
ls -la /etc/nginx/sites-enabled/
echo "--- nginx config test ---"
/usr/sbin/nginx -t 2>&1"}
